def minPath(grid, k):
    N = len(grid)
    min_path = []
    min_value = float('inf')
    min_path_index = -1

    def dfs(x, y, path):
        nonlocal min_value, min_path_index
        if len(path) == k:
            current_value = grid[x][y]
            if current_value < min_value:
                min_value = current_value
                min_path_index = len(path) - 1
            return

        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                dfs(nx, ny, path + [grid[nx][ny]])

    for i in range(N):
        for j in range(N):
            dfs(i, j, [grid[i][j]])

    if min_path_index == -1:
        return []

    return min_path[min_path_index:]

